/**
 * world-decisions: keeps each project's user decisions and picked art in front of the orchestrator,
 * and feeds the relevant ones into every subagent brief it sends.
 *
 * Source: <workspace>/<project>/DECISIONS.json (+ DECISIONS.md), generated by `.omp/scripts/steer.py`
 * from the project's STEER.jsonl decision database. Relevance ranking ("soft matching": words, meaning,
 * aliases) comes from `steer.py serve` (steer_rank.py), one Python process per omp process.
 *
 * Main session only (user, 2026-11-05: "the only agent that needs to know all decisions is the
 * orchestrator and he needs to basically feed all the relevant decisions to the sub-agents"):
 * - First time the session works on a project (its name in a prompt, the cwd, a tool call's path or a
 *   Unity instance `Name@hash`): the rules, the picked and rejected art, and the decisions most
 *   relevant to the request.
 * - Every later prompt: the decisions relevant to it that were not shown recently.
 * - A `task` call: the decisions relevant to each subagent brief are appended to that brief
 *   ("## User decisions (binding)"), and the orchestrator is told which ones went where.
 * - A tool call naming a record's `targets` or `aliases`: that record as a reminder.
 * - New records recorded mid-session are announced; compaction keeps a pointer and re-arms.
 * Subagent sessions get nothing from this extension: their brief carries what they need.
 */
import * as fs from "node:fs";
import * as path from "node:path";

const ROOT = path.resolve(
	path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")),
	"..", "..", "..",
);
const STEER = path.join(ROOT, ".omp", "scripts", "steer.py");
const FIRST_TOP = 12;
const PROMPT_TOP = 8;
const BRIEF_TOP = 10;
const MIN_SCORE = 0.55; // per-prompt injection: only clearly relevant records
const BRIEF_MIN = 0.35; // briefs: a few extra lines cost less than a missed decision
const RESHOW_AFTER = 30; // tool calls before a shown record may be shown again
const REMIND_EVERY = 25;
const MAX_REMINDERS = 6;

interface Rec {
	id: string;
	when: string;
	topic: string;
	affects: string[];
	aspect: string[];
	targets: string[];
	aliases?: string[];
	pick: string;
	decision: string;
	said: string;
	images: string[];
	status: string;
}
interface Db {
	project: string;
	generated: string;
	records: Rec[];
}
interface Ranked {
	id: string;
	score: number;
}

// ---- workspace scan -------------------------------------------------------------------------

let projectCache: { at: number; names: string[] } = { at: 0, names: [] };
function projects(): string[] {
	if (Date.now() - projectCache.at < 30_000) return projectCache.names;
	let names: string[] = [];
	try {
		names = fs
			.readdirSync(ROOT, { withFileTypes: true })
			.filter(d => d.isDirectory() && fs.existsSync(path.join(ROOT, d.name, "DECISIONS.json")))
			.map(d => d.name);
	} catch {
		// Workspace unreadable: no projects.
	}
	projectCache = { at: Date.now(), names };
	return names;
}

function loadDb(name: string): Db | undefined {
	try {
		return JSON.parse(fs.readFileSync(path.join(ROOT, name, "DECISIONS.json"), "utf8")) as Db;
	} catch {
		return undefined;
	}
}

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const NAME_CHARS = "A-Za-z0-9_\\-";

function mentioned(text: string, cwd: string | undefined): string[] {
	const rel = cwd ? path.relative(ROOT, cwd) : "";
	const cwdProject = rel && !rel.startsWith("..") && !path.isAbsolute(rel) ? rel.split(/[\\/]/)[0] : "";
	return projects().filter(
		n => n === cwdProject || new RegExp(`(^|[^${NAME_CHARS}])${esc(n)}([^${NAME_CHARS}]|$)`, "i").test(text),
	);
}

function targetRegex(glob: string): RegExp {
	return new RegExp(`(?<![A-Za-z0-9])${glob.split("*").map(esc).join("[A-Za-z0-9_.\\-/]*")}`, "i");
}

function aliasRegex(alias: string): RegExp {
	return new RegExp(`(?<![A-Za-z0-9])${esc(alias)}(e?s)?(?![A-Za-z0-9])`, "i");
}

// ---- ranking server (shared by every session in this omp process) ----------------------------

let server: { write(line: string): void; pending: Map<number, (r: Ranked[] | null) => void> } | null | undefined;
let nextId = 1;

function startServer(): typeof server {
	if (server !== undefined) return server;
	try {
		const proc = Bun.spawn(["python", STEER, "serve"], { stdin: "pipe", stdout: "pipe", stderr: "ignore" });
		const pending = new Map<number, (r: Ranked[] | null) => void>();
		server = { write: line => proc.stdin.write(line), pending };
		(async () => {
			const dec = new TextDecoder();
			let buf = "";
			for await (const chunk of proc.stdout) {
				buf += dec.decode(chunk);
				let nl = buf.indexOf("\n");
				while (nl >= 0) {
					const line = buf.slice(0, nl);
					buf = buf.slice(nl + 1);
					nl = buf.indexOf("\n");
					try {
						const msg = JSON.parse(line) as { id: number; results?: Ranked[] };
						pending.get(msg.id)?.(msg.results ?? null);
						pending.delete(msg.id);
					} catch {
						// Ignore a malformed line.
					}
				}
			}
			for (const resolve of pending.values()) resolve(null);
			pending.clear();
			server = null;
		})();
	} catch {
		server = null;
	}
	return server;
}

async function rank(project: string, query: string, limit: number, exclude: string[]): Promise<Ranked[] | null> {
	const s = startServer();
	if (!s || !query.trim()) return null;
	const id = nextId++;
	const { promise, resolve } = Promise.withResolvers<Ranked[] | null>();
	const timer = setTimeout(() => {
		s.pending.delete(id);
		resolve(null);
	}, 20_000); // first call loads the model and embeds the project once
	s.pending.set(id, r => {
		clearTimeout(timer);
		resolve(r);
	});
	s.write(`${JSON.stringify({ id, project: path.join(ROOT, project), query: query.slice(0, 4000), limit, exclude })}\n`);
	return promise;
}

// ---- formatting -----------------------------------------------------------------------------

function recLine(r: Rec, full = true): string {
	const labels = `${r.aspect.join(", ") || "no aspect"} · ${r.affects.join(", ")}`;
	const decision = full || r.decision.length <= 160 ? r.decision : `${r.decision.slice(0, 157)}…`;
	const imgs = full && r.images.length ? `\n  images: ${r.images.join(" ; ")}` : "";
	return `- [${r.id}] ${r.topic} (${labels}): ${decision}${full ? ` — user: ${r.said}` : ""}${imgs}`;
}

const RULES =
	"You are the orchestrator: these are the user's own decisions for this project. They override workspace " +
	"defaults, skill defaults and your own plans. Before deciding, building or asking the user anything, check " +
	"them; a question already answered here is not asked again. Every subagent brief must carry the decisions " +
	"and picked image paths it depends on (relevant ones are appended to `task` briefs automatically; add any " +
	"the ranking missed). Record every new user decision before acting on it: `python .omp/scripts/steer.py " +
	"--project <project> add|pick ...` with the user's exact words (only an explicit like is a pick, only an " +
	"explicit dislike a rejection). Search: `steer.py find --like \"<words>\"` or `--affects/--aspect/--target`.";

// ---- extension ------------------------------------------------------------------------------

interface Ctx {
	cwd?: string;
	agent?: { kind?: string };
}
interface Api {
	on(
		event: string,
		handler: (event: { prompt?: unknown; input?: unknown; toolName?: unknown }, ctx: Ctx) => Promise<unknown>,
	): void;
}

export default function worldDecisions(pi: Api): void {
	// Per-session state: the factory is rebound for every session.
	const seen = new Map<string, { generated: string; ids: Set<string> }>();
	const shownAt = new Map<string, number>(); // "project:id" -> tool-call count when last shown
	let calls = 0;
	let lastPrompt = "";

	const isMain = (ctx: Ctx) => (ctx?.agent?.kind ?? "main") === "main";
	const recent = (key: string) => {
		const at = shownAt.get(key);
		return at !== undefined && calls - at < RESHOW_AFTER;
	};

	async function relevant(n: string, db: Db, query: string, top: number, minScore: number): Promise<Rec[] | null> {
		const exclude = db.records.filter(r => recent(`${n}:${r.id}`) || r.pick).map(r => r.id);
		const ranked = await rank(n, query, top, exclude);
		if (!ranked) return null;
		const byId = new Map(db.records.map(r => [r.id, r]));
		return ranked.filter(x => x.score >= minScore).flatMap(x => byId.get(x.id) ?? []);
	}

	function markShown(n: string, recs: Rec[]): void {
		for (const r of recs) shownAt.set(`${n}:${r.id}`, calls);
	}

	async function firstTouch(n: string, db: Db, query: string): Promise<string> {
		const md = path.join(ROOT, n, "DECISIONS.md");
		const liked = db.records.filter(r => r.pick === "liked");
		const rejected = db.records.filter(r => r.pick === "rejected");
		const parts = [`<world-decisions project="${n}" file="${md}">`, RULES];
		if (liked.length) parts.push("Art the user picked (build to these):", ...liked.map(r => recLine(r)));
		if (rejected.length) parts.push("Art the user rejected (never build like these):", ...rejected.map(r => recLine(r)));
		const rel = await relevant(n, db, query, FIRST_TOP, 0.3);
		if (rel) {
			if (rel.length) parts.push("Decisions most relevant to the current request:", ...rel.map(r => recLine(r)));
			markShown(n, rel);
			parts.push(`${db.records.length - liked.length - rejected.length} decisions in force in total; full text: ${md}.`);
		} else {
			const rest = db.records.filter(r => !r.pick);
			parts.push("Decisions in force (index; ranking unavailable):", ...rest.map(r => recLine(r, false)));
		}
		markShown(n, [...liked, ...rejected]);
		parts.push("</world-decisions>");
		return parts.join("\n");
	}

	/** Digest on first touch, announcements of new records afterwards. */
	async function sync(names: string[], query: string): Promise<string[]> {
		const out: string[] = [];
		for (const n of names) {
			const db = loadDb(n);
			if (!db) continue;
			const prev = seen.get(n);
			if (!prev) {
				out.push(await firstTouch(n, db, query));
			} else if (prev.generated !== db.generated) {
				const fresh = db.records.filter(r => !prev.ids.has(r.id));
				if (fresh.length) {
					out.push(`<world-decisions project="${n}" update="true">\nNew user decisions recorded (binding):\n${fresh.map(r => recLine(r)).join("\n")}\n</world-decisions>`);
					markShown(n, fresh);
				}
			}
			seen.set(n, { generated: db.generated, ids: new Set(db.records.map(r => r.id)) });
		}
		return out;
	}

	function reminders(text: string): string[] {
		const hits: string[] = [];
		for (const n of seen.keys()) {
			const db = loadDb(n);
			if (!db) continue;
			for (const r of db.records) {
				if (hits.length >= MAX_REMINDERS) break;
				const key = `${n}:${r.id}`;
				const at = shownAt.get(key);
				if (at !== undefined && calls - at < REMIND_EVERY) continue;
				const named =
					r.targets?.some(t => targetRegex(t).test(text)) || r.aliases?.some(a => a.length > 2 && aliasRegex(a).test(text));
				if (!named) continue;
				shownAt.set(key, calls);
				hits.push(`${n} ${recLine(r)}`);
			}
		}
		return hits.length
			? [`<world-decisions reminder="true">\nThis call touches things the user decided about. Follow these over any default, skill or plan:\n${hits.join("\n")}\n</world-decisions>`]
			: [];
	}

	/** Append the decisions relevant to each subagent brief to that brief. */
	async function feedBriefs(input: Record<string, unknown>): Promise<{ input?: Record<string, unknown>; note?: string }> {
		const tasks = Array.isArray(input.tasks) ? (input.tasks as Record<string, unknown>[]) : null;
		if (!tasks) return {};
		const context = typeof input.context === "string" ? input.context : "";
		const notes: string[] = [];
		const newTasks = [];
		for (const t of tasks) {
			const brief = typeof t.task === "string" ? t.task : "";
			const names = mentioned(`${context}\n${brief}`, undefined);
			const scope = names.length ? names : [...seen.keys()];
			const blocks: string[] = [];
			const fed: string[] = [];
			for (const n of scope) {
				const db = loadDb(n);
				if (!db) continue;
				const ranked = await rank(n, `${context}\n${brief}`, BRIEF_TOP, []);
				if (!ranked) continue;
				const byId = new Map(db.records.map(r => [r.id, r]));
				const recs = ranked.filter(x => x.score >= BRIEF_MIN).flatMap(x => byId.get(x.id) ?? []);
				if (!recs.length) continue;
				blocks.push(
					`### ${n}\n${recs.map(r => recLine(r)).join("\n")}\nMore: \`python .omp/scripts/steer.py --project ${path.join(ROOT, n)} find --like "<words>"\`, digest ${path.join(ROOT, n, "DECISIONS.md")}.`,
				);
				fed.push(`${n}: ${recs.map(r => r.id).join(", ")}`);
			}
			if (blocks.length) {
				newTasks.push({
					...t,
					task:
						`${brief}\n\n## User decisions (binding)\nThe user's own decisions that apply to this task, with his words. ` +
						`They override skill and kit defaults; a conflict with this brief stops you and goes in your report.\n` +
						blocks.join("\n"),
				});
				notes.push(`${typeof t.name === "string" ? t.name : "task"} ← ${fed.join(" | ")}`);
			} else {
				newTasks.push(t);
			}
		}
		if (!notes.length) return {};
		return {
			input: { ...input, tasks: newTasks },
			note:
				"<world-decisions briefs=\"true\">\nAppended relevant user decisions to the briefs: " +
				`${notes.join("; ")}. Check they cover what each task depends on; add any the ranking missed in a follow-up message only after the subagent's first tool call.\n</world-decisions>`,
		};
	}

	pi.on("before_agent_start", async (event, ctx) => {
		if (!isMain(ctx)) return;
		const prompt = typeof event?.prompt === "string" ? event.prompt : "";
		lastPrompt = prompt;
		const names = mentioned(prompt, ctx?.cwd);
		const blocks = await sync(names, prompt);
		for (const n of seen.keys()) {
			if (names.includes(n) && blocks.some(b => b.includes(`project="${n}" file=`))) continue; // just got the digest
			const db = loadDb(n);
			if (!db) continue;
			const rel = await relevant(n, db, prompt, PROMPT_TOP, MIN_SCORE);
			if (rel?.length) {
				markShown(n, rel);
				blocks.push(`<world-decisions project="${n}" relevant="true">\nUser decisions relevant to this request (binding):\n${rel.map(r => recLine(r)).join("\n")}\n</world-decisions>`);
			}
		}
		if (!blocks.length) return;
		return { message: { customType: "world-decisions", content: blocks.join("\n\n"), display: false } };
	});

	pi.on("tool_call", async (event, ctx) => {
		if (!isMain(ctx)) return;
		calls++;
		const input = (event?.input ?? {}) as Record<string, unknown>;
		let text = "";
		try {
			text = JSON.stringify(input);
		} catch {
			return;
		}
		const blocks = [...(await sync(mentioned(text, ctx?.cwd), lastPrompt)), ...reminders(text)];
		let revised: Record<string, unknown> | undefined;
		if (event?.toolName === "task") {
			const fed = await feedBriefs(input);
			if (fed.input) revised = fed.input;
			if (fed.note) blocks.push(fed.note);
		}
		const result: { input?: Record<string, unknown>; additionalContext?: string } = {};
		if (revised) result.input = revised;
		if (blocks.length) result.additionalContext = blocks.join("\n\n");
		return Object.keys(result).length ? result : undefined;
	});

	pi.on("session.compacting", async (_event, ctx) => {
		if (!isMain(ctx) || !seen.size) return;
		return {
			context: [
				"World decisions in force (binding user decisions and picked art; re-read before continuing): " +
					[...seen.keys()].map(n => `${n} -> ${path.join(ROOT, n, "DECISIONS.md")}`).join("; "),
			],
		};
	});

	pi.on("session_compact", async (_event, ctx) => {
		if (!isMain(ctx)) return;
		seen.clear();
		shownAt.clear();
	});
}
